BEGIN TRANSACTION;
CREATE TABLE decisao (
  id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT NOT NULL, area TEXT, titulo TEXT NOT NULL,
  contexto TEXT, opcoes TEXT, escolha TEXT, motivo TEXT, numeros TEXT, revisar_em TEXT,
  resultado TEXT, resultado_em TEXT);
CREATE TABLE memoria (
  id INTEGER PRIMARY KEY AUTOINCREMENT, tipo TEXT NOT NULL, texto TEXT NOT NULL,
  criada_em TEXT NOT NULL, ativa INTEGER NOT NULL DEFAULT 1);
CREATE TABLE numero (
  id INTEGER PRIMARY KEY AUTOINCREMENT, chave TEXT NOT NULL, valor REAL NOT NULL,
  ref TEXT NOT NULL, fonte TEXT NOT NULL, registrado_em TEXT NOT NULL);
CREATE TABLE pendencia (
  id INTEGER PRIMARY KEY AUTOINCREMENT, texto TEXT NOT NULL, quando TEXT NOT NULL,
  origem TEXT, concluida_em TEXT, criada_em TEXT NOT NULL);
CREATE TABLE problema (
  id INTEGER PRIMARY KEY AUTOINCREMENT, area TEXT NOT NULL, titulo TEXT NOT NULL,
  descricao TEXT, impacto INTEGER NOT NULL DEFAULT 3, responsavel TEXT, desde TEXT,
  tentado TEXT, proximo_passo TEXT, status TEXT NOT NULL DEFAULT 'aberto',
  criado_em TEXT NOT NULL, atualizado_em TEXT NOT NULL);
12/11: Victor acrescentou que observa no dia a dia falta de capacidade para a função de PCP e resistência recorrente a assumir responsabilidades pelos erros. Trata-se da avaliação de Victor, não diagnóstico independente. A recomendação do conselheiro passa a ser preparar substituição no PCP, com controle temporário das mudanças de prioridade. Remanejamento apenas se existir vaga real compatível e evidência de capacidade. Não há decisão de demissão ou remanejamento tomada.
12/11: Victor informou que quer encontrar um substituto com perfil adequado e relata má experiência com candidatos de PCP de multinacionais/produção seriada da região, por diferenças em relação ao processo da Labplan. Busca deve priorizar competências demonstradas e adaptação à produção sob encomenda, não experiência prévia em PCP como filtro principal.
