INSERT INTO "decisao" VALUES(1,'2026-11-12','rh','Equiparar salário de Nemuel ao de Evelyn','Victor confirmou que Evelyn não é mais coordenadora e realiza o mesmo trabalho de Nemuel.',NULL,'Aumentar o salário de Nemuel para igualar ao de Evelyn, sem reduzir o salário dela.','Mesma função na prática, conforme informação de Victor.',NULL,NULL,NULL,NULL);
INSERT INTO "decisao" VALUES(2,'2026-11-12','rh','Substituir primeiro o PCP e depois o encarregado de produção','Victor relata dificuldades recorrentes de André no PCP e de Nattan na liderança da produção.',NULL,'Preparar e executar primeiro a substituição de André no PCP; depois, a substituição de Nattan como encarregado de produção.',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "decisao" VALUES(3,'2026-11-16','rh','Adiar ajuste de Nemuel e planejar aumento para Nemuel e Evelyn após reajuste anual','Substitui o plano anterior de aumentar apenas Nemuel imediatamente para igualar ao salário de Evelyn.',NULL,'Não aumentar Nemuel agora; planejar aumento para ambos após o reajuste salarial do início do ano.','Victor quer evitar que o reajuste anual incida sobre o aumento que pretende conceder. Essa premissa depende de confirmação com o contador e a convenção aplicável.',NULL,NULL,NULL,NULL);
INSERT INTO "decisao" VALUES(4,'2026-11-16','rh','Meta salarial aproximada de R$ 2.600 para Nemuel e Evelyn','Complementa o plano de aguardar o reajuste salarial do início do ano para aumentar ambos, sem alteração imediata da folha.',NULL,'Victor pretende levar Nemuel e Evelyn a aproximadamente R$ 2.600 mensais cada, mantendo o mesmo salário para ambos.',NULL,'Fonte: declaração direta de Victor. Valor-alvo aproximado: R$ 2.600 por pessoa. Não é salário vigente nem valor final aprovado para lançamento.',NULL,NULL,NULL);
INSERT INTO "memoria" VALUES(1,'fato','Victor enviou o Extrato Mensal da folha da Labplan de outubro/2026, emitido em 03/11/2026. Fonte arquivada em relatorios/contador-2026-10.pdf; estrutura nominal e cargos em equipe/2026-10-estrutura.json na pasta de dados. É a fotografia da folha de outubro, não organograma confirmado nem quadro atual completo; falta confirmar pessoas fora da folha, comercial/Cartê e subordinações.','2026-11-12 13:13:33',1);
INSERT INTO "memoria" VALUES(2,'fato','Correção de Victor: Nilvan Santana Pereira atua como auxiliar de operação, também limpa a empresa e a mantém organizada. Não trabalha no almoxarifado; almoxarife é apenas o cargo que aparece na folha de outubro/2026. Função real registrada em equipe/2026-10-estrutura.json.','2026-11-12 13:15:44',1);
INSERT INTO "memoria" VALUES(3,'fato','Victor informou que Evelyn Brenda Freire de Oliveira não é mais coordenadora técnica e faz o mesmo trabalho de Nemuel Nascimento da Cruz. Segundo Victor, ambos deveriam receber o mesmo salário. Valor-alvo e data do ajuste ainda não definidos.','2026-11-12 13:19:18',1);
INSERT INTO "memoria" VALUES(4,'fato','Victor informou que Itana substitui Wilma no financeiro, com o mesmo salário e condições de Wilma, e ainda não constava na folha de outubro/2026. Jaime é novo marceneiro, assim como Alexandre (nome usado por Victor); não foi informado o salário de Jaime nem confirmado se Alexandre é Alexandro Ferreira de Jesus da folha. Complementos registrados em equipe/2026-10-estrutura.json sem alterar o quadro histórico da folha.','2026-11-12 13:22:30',1);
INSERT INTO "memoria" VALUES(5,'fato','Victor confirmou que Jaime, novo marceneiro, recebe o mesmo salário de Alexandre. O valor ficou registrado por referência a Alexandre, sem presumir que ele seja Alexandro Ferreira de Jesus da folha. Essa confirmação substitui a informação anterior de salário de Jaime não informado.','2026-11-12 13:23:01',1);
INSERT INTO "memoria" VALUES(6,'fato','Victor identifica o supervisor de produção Walyson Nattan como Nattan e descreve sua atuação real como encarregado, com entrega insatisfatória. Relata fragilidade técnica e de liderança, especialmente na marcenaria. Avaliação detalhada registrada no mapa de problemas de RH. Victor não exige relatórios desse posto; ausência de relatórios não é problema por si.','2026-11-12 14:44:04',1);
INSERT INTO "memoria" VALUES(7,'fato','Victor esclareceu que a manutenção das máquinas que pediu para lembrar é terceirizada. Quer apenas lembrar de marcar com um técnico, sem ampliar o pedido para planejamento de escopo, equipe ou parada.','2026-11-12 16:15:25',1);
INSERT INTO "memoria" VALUES(8,'fato','Atualização de Victor: não fará o aumento de Nemuel agora; pretende aumentar Nemuel e Evelyn após o reajuste salarial do início do ano, para evitar incidência sobre o aumento planejado. É intenção, sem execução, valores ou vigência confirmados; premissa a conferir com contador. Substitui o plano anterior de aumento imediato apenas para Nemuel.','2026-11-16 11:54:09',1);
INSERT INTO "memoria" VALUES(9,'fato','Victor definiu como intenção levar Nemuel e Evelyn a aproximadamente R$ 2.600 mensais cada, após o reajuste salarial do início do ano. O valor é aproximado; não houve execução nem definição de vigência exata. Complementa e atualiza os registros anteriores em que o valor-alvo ainda era desconhecido.','2026-11-16 11:55:52',1);
INSERT INTO "memoria" VALUES(10,'fato','Victor forneceu a relação dos pedidos de venda do Pontta de 2026 em duas mensagens. Fonte, dados estruturados, lista CSV e ranking por cliente guardados em analises/vendas-2026/ na pasta de dados. Cálculos em organizar_pedidos.py e resumo.json. Base de pedidos/vendas, não faturamento fiscal; dados recebidos não têm total de controle nem prova de paginação completa. Usar esta base em vez dos orçamentos do CRM para análises destas vendas.','2026-11-17 13:01:43',1);
INSERT INTO "numero" VALUES(1,'vendas_pedidos_2026_relacao_recebida',4978610.92,'2026','Pedidos de venda do Pontta colados por Victor; 56 pedidos únicos, datas de venda de 23/01 a 12/11/2026. Todos os status recebidos; inclui um pedido zerado. Soma calculada e conciliada por script, não faturamento fiscal.','2026-11-17 13:01:43');
INSERT INTO "pendencia" VALUES(1,'Revisar com o contador a equiparação salarial de Evelyn Brenda e Nemuel: Evelyn não é mais coordenadora e executa o mesmo trabalho de Nemuel. Definir salário comum e atualizar o cargo/função registrado, sem reduzir salário unilateralmente.','2026-11-13','Pedido direto de Victor no Telegram','2026-11-12 13:20:30','2026-11-12 13:19:37');
INSERT INTO "pendencia" VALUES(2,'Definir a vigência do aumento de Nemuel e solicitar ao contador a equiparação ao salário de Evelyn. A decisão de aumentar Nemuel já foi tomada por Victor. Revisar também o cargo registrado de Evelyn.','2026-11-13','Decisão de Victor no Telegram','2026-11-16 11:54:09','2026-11-12 13:20:30');
INSERT INTO "pendencia" VALUES(3,'Revisar ajustes no Dinabox: tamanho de fundo e profundidade dos rasgos em gavetas e módulos; usinagem das gavetas; posição de tambor minifix em peças; orçamento de cabideiro e vidraçaria avulsa. Pedido de Victor, sem horário definido; colocado na pauta de amanhã como sugestão.','2026-11-13','Pedido direto de Victor no Telegram','2026-11-16 11:54:08','2026-11-12 15:07:36');
INSERT INTO "pendencia" VALUES(4,'Marcar uma manutenção agressiva nas máquinas, conforme pedido de Victor. Definir escopo da revisão, equipe responsável e janela de parada. Sem horário solicitado; incluído na pauta de amanhã como sugestão. Não há manutenção agendada nem alteração em sistemas ou no perfil do agente de manutenção.','2026-11-13','Pedido direto de Victor no Telegram','2026-11-12 16:15:25','2026-11-12 16:14:31');
INSERT INTO "pendencia" VALUES(5,'Marcar com um técnico terceirizado a manutenção das máquinas. Victor pediu apenas o lembrete para fazer o agendamento.','2026-11-13','Correção de Victor no Telegram; substitui a pendência 4','2026-11-16 11:54:08','2026-11-12 16:15:24');
INSERT INTO "pendencia" VALUES(6,'Acompanhar busca de profissional para ajustar a galeria do Dinabox: Victor já divulgou em grupo de WhatsApp. Preparar reunião com equipe técnica e projetistas para colher problemas e melhorias. Preservar lista: tamanho de fundo/profundidade dos rasgos em gavetas e módulos; usinagem de gavetas; posição de tambor minifix; orçamento de cabideiro e vidraçaria avulsa. Contratação, reunião e ajustes ainda não confirmados. Data apenas para retomar acompanhamento, sugerida pelo conselheiro; não é prazo assumido por Victor.','2026-11-23','Atualização de Victor no Telegram',NULL,'2026-11-16 11:54:07');
INSERT INTO "pendencia" VALUES(7,'Acompanhar orçamentos e recebimento das peças para manutenção terceirizada. Victor está fazendo orçamentos e comprando peças; marcar com técnico após recebê-las. Manutenção ainda não agendada. Data apenas para retomar acompanhamento, sugerida pelo conselheiro; não é prazo assumido por Victor.','2026-11-23','Atualização de Victor no Telegram',NULL,'2026-11-16 11:54:08');
INSERT INTO "pendencia" VALUES(8,'Revisar plano de aumentar Nemuel e Evelyn após o reajuste salarial do início do ano. Victor decidiu não aumentar Nemuel agora. Confirmar com contador data-base, regras da convenção e eventual compensação de aumentos antes de presumir economia. Valores, vigência e manutenção da intenção de igualar os salários ainda a confirmar. Revisar cargo registrado de Evelyn. Data apenas para retomar acompanhamento, sugerida pelo conselheiro; não é prazo assumido por Victor.','2026-11-23','Atualização de Victor no Telegram','2026-11-16 11:55:53','2026-11-16 11:54:08');
INSERT INTO "pendencia" VALUES(9,'Revisar o plano de aumentar Nemuel e Evelyn para aproximadamente R$ 2.600 mensais cada após o reajuste salarial do início do ano. Valor-alvo informado por Victor, ainda aproximado; não houve alteração vigente. Confirmar com contador data-base, convenção e regra de compensação; definir valor final e vigência e revisar cargo registrado de Evelyn. Data de acompanhamento sugerida pelo conselheiro, não prazo de execução assumido por Victor.','2026-11-23','Atualização de Victor; substitui pendência 8',NULL,'2026-11-16 11:55:52');
INSERT INTO "problema" VALUES(1,'rh','André do PCP: antecipação de demandas sem validar prioridade e autorização','Relato de Victor: cliente com prazo final em 15/01/2027 foi apresentado pelo comercial/técnico como entrega ainda neste ano. André adiantou solicitações de compras e considerou incluir no planejamento de entrega, presumindo que a antecipação já tinha sido combinada com Victor. Victor identificou e questionou antes de prosseguir. André respondeu: Achei que já tinha combinado com você. Victor relata recorrência de situações semelhantes e percebe dificuldade em demandas que exigem raciocínio. Não há confirmação de compra efetivada ou entrega alterada. Avaliação de perfil ainda não concluída; falta confirmar regra de alçada, treinamento e exemplos anteriores. Riscos potenciais: antecipação de desembolso, alteração de prioridades e comprometimento de outras entregas.',4,'André Luiz Moraes da Silva',NULL,'Victor identificou a situação e perguntou a André o que havia ocorrido.
INSERT INTO "problema" VALUES(2,'rh','Nattan: insuficiência técnica e de liderança na produção, segundo Victor','Segundo Victor, Nattan tem cargo de supervisor de produção, mas atua como encarregado com entrega insatisfatória. Victor relata que ele não sabe operar os equipamentos nem orientar adequadamente manutenção básica como limpeza e lubrificação; entende que deveria ao menos guiar e cobrar os operadores. Relata falta de respeito da equipe, principalmente dos marceneiros, postura insuficiente para conduzir a situação e perda de controle do setor de marcenaria. Também avalia dificuldade de raciocínio lógico. São relatos e avaliações de Victor, sem verificação independente. Não produzir relatórios não deve ser tratado como deficiência neste caso: Victor disse explicitamente que não precisa deles. Ainda falta apurar treinamento, rotinas, alçadas e respaldo da liderança.',4,'Walyson Nattan Rosa da Rocha Santos de Jesus',NULL,'12/11: Decisão de Victor: substituir o encarregado de produção depois de trocar o PCP. Não há data definida nem substituto contratado.','Manter controles e cobertura da produção durante a troca do PCP; preparar a substituição de Nattan como etapa seguinte, sem deixar a marcenaria sem condução.','aberto','2026-11-12 14:44:03','2026-11-12 14:52:15');
INSERT INTO "problema" VALUES(3,'producao','Pendências de montagem: divergência sobre origem e atribuição de responsabilidade','Victor relata que está cobrando o supervisor de montagem por detalhes e pendências. Segundo informação recebida do gerente da loja, vendedores, técnicos e projetistas atribuem problemas de montagem a erros de fabricação. Victor contesta que essa seja uma explicação geral e informa que peças avariadas são substituídas imediatamente. Sua hipótese, ainda não verificada, é que a percepção se forme nas visitas às obras com o supervisor de montagem, que poderia atribuir as falhas à fábrica. Não há evidência apresentada de fala específica, intenção do supervisor ou causa técnica dos casos. Substituição rápida não prova nem exclui erro de fabricação; origem da avaria e motivo da permanência da pendência precisam ser avaliados separadamente.',4,NULL,NULL,NULL,'Recomendação ainda não decidida: pedir ao gerente exemplos concretos; revisar pendências com supervisor de montagem e técnico/qualidade, usando fotos, datas de identificação, solicitação, reposição e execução; distinguir fabricação, projeto, transporte/manuseio, montagem e condições da obra. Definir responsável e prazo pela solução sem esperar concluir a atribuição da causa. Não acusar o supervisor com base apenas na hipótese.','aberto','2026-11-12 15:11:23','2026-11-12 15:11:23');
INSERT INTO "relatorio" VALUES(1,'contador','2026-10','/opt/data/conselheiro-dados/relatorios/contador-2026-10.pdf','2026-11-12 13:12:44','Folha mensal da Labplan; emitida em 03/11/2026. Base nominal de cargos, não confirma organograma real nem equipe fora da folha.');
INSERT INTO "relatorio" VALUES(2,'pontta-pedidos','2026','/opt/data/conselheiro-dados/relatorios/pontta-pedidos-2026.txt','2026-11-17 13:01:43','Relação de pedidos enviada por Victor em duas mensagens do Telegram. Valores de vendas por data da venda, não faturamento fiscal. Sem total geral de controle ou confirmação independente de paginação.');
